              bodyType: newObj.userData.physicsBodyType ?? 2,
              friction: newObj.userData.physicsFriction ?? 0.3,
              restitution: newObj.userData.physicsRestitution ?? 0.2,
              linearDamping: newObj.userData.physicsLinearDamping ?? 0.01,
